P.joinpath('index.html').write_text(shell('Lustrzane Produkty — personalizowane vouchery i dekoracje','Personalizowane vouchery, certyfikaty, wizytówki i produkty lustrzane dla wyjątkowych marek beauty. Odkryj kolekcję.',home))
for p in products:
 related=[x for x in products if x['slug']!=p['slug'] and x['category']==p['category']]
 related+=( [x for x in products if x not in related and x['slug']!=p['slug']])
 body=f'''<div class="container breadcrumb"><a href="/">Strona główna</a><span>/</span><a href="/#produkty">Kolekcja</a><span>/</span><span>{p['name']}</span></div><section class="container product-detail"><div class="detail-gallery"><button class="main-product-image" data-gallery="product" data-src="{p['image']}"><img src="{p['image']}" alt="{p['name']} — pełny widok produktu" width="850" height="1000" fetchpriority="high"><span>Kliknij, aby przyjrzeć się detalom ↗</span></button><div class="thumbnail-row"><button class="thumb active" data-view="full" aria-label="Pełny widok produktu" aria-pressed="true"><img src="{p['image']}" alt="Pełny widok" width="90" height="90"></button><button class="thumb" data-view="detail" aria-label="Powiększenie detalu tego samego zdjęcia" aria-pressed="false"><img src="{p['image']}" alt="Detal — powiększenie" width="90" height="90"></button><span>Widok całości / detal</span></div></div><div class="detail-copy"><p class="eyebrow">{p['category']} · KOLEKCJA LUSTRZANA</p><h1>{p['name']}</h1><p class="detail-tagline">{p['short']}</p><p>{p['description']}</p><div class="detail-divider"></div><fieldset class="finish-options"><legend>Preferowane wykończenie</legend><label><input type="radio" name="finish" value="Złote" checked><span><i class="swatch gold"></i> Złote</span></label><label><input type="radio" name="finish" value="Srebrne"><span><i class="swatch silver"></i> Srebrne</span></label><label><input type="radio" name="finish" value="Do ustalenia"><span>Do ustalenia</span></label></fieldset><p class="fine">Dostępność wykończenia potwierdzimy dla wybranego produktu.</p><label class="quantity-label">Planowana liczba sztuk <input id="quantity" type="number" min="1" max="100000" value="1" step="1"></label><p class="personal-note">✧ Zakres personalizacji ustalamy indywidualnie.</p><div class="price-slot"><span>Indywidualna wycena</span><small>Cenę całkowitą potwierdzimy w ofercie.</small></div><a class="btn primary inquiry-cta" href="mailto:grafiki.beauty@gmail.com">Zapytaj o produkt {icon('arrow')}</a><p class="fine">Bez zobowiązań. Ustalimy szczegóły i możliwości realizacji.</p></div></section>{product_safety(p)}<section class="section container"><div class="section-heading"><div><p class="eyebrow">SPÓJNA KOLEKCJA TWOJEJ MARKI</p><h2>Pięknie <em>razem.</em></h2></div>{button('Cała kolekcja','/#produkty','secondary')}</div><div class="product-grid related-grid">{''.join(card(x) for x in related[:3])}</div></section>'''
 d=P/'produkty'/p['slug'];d.mkdir(parents=True,exist_ok=True);d.joinpath('index.html').write_text(shell(p['name']+' — Lustrzane Produkty',p['description'],body,'/produkty/'+p['slug']+'/'))
(P/'404.html').write_text(shell('Nie znaleziono strony — Lustrzane Produkty','Wróć do kolekcji lustrzanych produktów.','<section class="section container legal"><p class="eyebrow">404</p><h1>To odbicie nam umknęło.</h1><p>Nie znaleźliśmy tej strony. Odkryj naszą kolekcję.</p>'+button('Wróć do kolekcji','/#produkty')+'</section>'))
# Keep the searchable catalog synchronized with product edits.
data=P/"data.js"
text=data.read_text()
text=re.sub(r"window.CATALOG=.*?;", "window.CATALOG="+json.dumps([{k:p[k] for k in ("name","slug","category","image")} for p in products],ensure_ascii=False)+";", text, count=1)
data.write_text(text)

